const cfg=$('V2 Config & Guardrails').first().json;
if(!cfg.ai_enabled) return [];
const persistedComments=$input.all().flatMap(i=>Array.isArray(i.json)?i.json:[i.json]).filter(c=>c&&c.post_id&&!c.error&&!c.code);
const posts=$('Load Posts for Comments').all().flatMap(i=>Array.isArray(i.json)?i.json:[i.json]).filter(p=>p&&p.id&&!p._v2_error);
const byPost=new Map();
for(const c of persistedComments){const arr=byPost.get(c.post_id)||[]; arr.push(c); byPost.set(c.post_id,arr);}
return posts.slice(0,cfg.max_ai_analyses_per_run||1).map(p=>({json:{post:p,comments:(byPost.get(p.id)||[]).sort((a,b)=>(b.like_count||0)-(a.like_count||0)).slice(0,80)}}));

return $input.all().map(item=>{
  const row=item.json;
  const post=row.post||{};
  const comments=row.comments||[];
  const commentsText=comments.map((c,i)=>`${i+1}. @${c.comment_user||'usuario'}: ${c.comment_text||''} | likes: ${c.like_count||0}`).join('
');
  const dataBlock=`Legenda do post: ${post.caption||''}
Curtidas: ${post.like_count||0}
Comentarios: ${post.comment_count||0}
Visualizacoes: ${post.view_count||0}
Compartilhamentos: ${post.share_count||0}
Data da postagem: ${post.taken_at||''}
URL: ${post.post_url||''}

Comentarios analisados (${comments.length}):
${commentsText||'Nenhum comentario capturado.'}`;
  return {json:{post_id:post.id,target_id:post.target_id,client_id:post.client_id,data_block:dataBlock,comments_count_analyzed:comments.length}};
});

const bases=$('Prepare AI Prompt V2').all();
const extractText=r=>{
  if(typeof r==='string') return r;
  const parts=r?.content?.parts;
  if(Array.isArray(parts)) return parts.map(p=>p?.text||'').join('');
  return r?.output ?? r?.text ?? r?.message?.content ?? null;
};
return $input.all().map((item,idx)=>{
  const base=(bases[idx]||bases[0]||{}).json||{};
  const raw=item.json;
  const rawText=extractText(raw);
  let parsed;
  if(rawText && typeof rawText==='string'){
    try{ parsed=JSON.parse(rawText.replace(/```json|```/g,'').trim()); }
    catch(e){ parsed={sentiment:'neutro',risk_level:'baixo',risk_status:'novo',ai_topics:[],ai_entities:[],risk_reason:'Falha ao interpretar resposta da IA.',summary:rawText,recommended_action:'Revisar manualmente.',raw_error:e.message,raw_text:rawText}; }
  } else {
    parsed={sentiment:'neutro',risk_level:'baixo',risk_status:'novo',ai_topics:[],ai_entities:[],risk_reason:'Resposta da IA vazia ou em formato inesperado.',summary:null,recommended_action:'Revisar manualmente.',raw_node_output:raw};
  }
  return {json:{target_id:base.target_id,client_id:base.client_id,content_type:'post',content_id:base.post_id,sentiment:parsed.sentiment||'neutro',ai_topics:parsed.ai_topics||[],ai_entities:parsed.ai_entities||[],risk_level:parsed.risk_level||'baixo',risk_status:parsed.risk_status||'novo',risk_reason:parsed.risk_reason||null,summary:parsed.summary||null,recommended_action:parsed.recommended_action||null,polarization_level:parsed.polarization_level||null,engagement_quality:parsed.engagement_quality||null,raw_ai_response:parsed,created_at:new Date().toISOString(),_v2_finish_reason:raw?.finishReason||null}};
});

const a=$('Validate Tenant Scope').first().json.request_context.account;
const results=$input.all();
const isError=r=>Boolean(r?.error||r?.code||(Number.isFinite(Number(r?.statusCode))&&Number(r.statusCode)>=400));
const attempted=results.length;
const failedItems=results.filter(i=>isError(i.json)).length;
const success=Math.max(0,attempted-failedItems);
const status=attempted===0?'success':failedItems===0?'success':success>0?'partial':'error';
return [{json:{target_id:a.target_id,social_account_id:a.id,client_id:a.client_id,platform:'instagram',started_at:a.started_at,finished_at:new Date().toISOString(),status,posts_collected:0,comments_collected:0,error_message:failedItems?'one or more ai_analysis upserts failed':null,metadata:{workflow_id:$workflow.id,execution_id:String($execution.id),pipeline_version:'v2',shadow_mode:true,stage:'ai_analysis',ai_calls:attempted,ai_analyses_attempted:attempted,ai_analyses_success:success,ai_analyses_failed:failedItems,errors_count:failedItems,warnings_count:status==='partial'?1:0}}}];
